export const TYPES={
 auth:{name:'本人確認',label:'なりすまし',pattern:'GLIDER / すり抜ける',rule:'本人と、鍵の送信先が一致する通信だけ通す。',patch:'本人と送信先を照合',hint:'小さな塊が斜めに移動する。',color:'#edb96d'},
 share:{name:'共有領域',label:'権限の抜け',pattern:'BRANCH / 枝分かれ',rule:'ファイルの持ち主と、閲覧者が一致する通信だけ通す。',patch:'持ち主と閲覧者を照合',hint:'一本の枝から、隣の領域へ増殖する。',color:'#d78eaf'},
 flood:{name:'入口',label:'大量リクエスト',pattern:'PULSE / 押し寄せる',rule:'同じ相手からの通信は、毎秒20件まで通す。',patch:'相手ごとに通信量を制限',hint:'横に広がる波が、繰り返し押し寄せる。',color:'#c2a2ed'},
 exfil:{name:'データ出口',label:'情報の持ち出し',pattern:'SIPHON / 外へ抜ける',rule:'「社内資料」は、社内の宛先だけに送れる。公開資料は外部も可。',patch:'資料と宛先を照合',hint:'データの粒が、外側へひとつずつ抜ける。',color:'#79cbd4'}
};
export const ORDER=Object.keys(TYPES);
const FORMS=[
 ['auth',false,'AOI','UNKNOWN'],['share',true,'REN','REN'],['flood',false,'UNKNOWN','74'],['exfil',true,'公開資料','外部'],
 ['share',false,'AOI','UNKNOWN'],['auth',true,'MIKA','MIKA'],['exfil',false,'社内資料','外部'],['flood',true,'REN','8'],
 ['auth',false,'REN','UNKNOWN'],['share',true,'AOI','AOI'],['flood',false,'UNKNOWN','92'],['exfil',true,'社内資料','社内'],
 ['share',false,'MIKA','UNKNOWN'],['auth',true,'REN','REN'],['exfil',false,'社内資料','外部'],['flood',true,'MIKA','12']
];
export class Shift{
 constructor(){this.time=0;this.running=false;this.started=false;this.done=false;this.data=100;this.trust=100;this.allowed=0;this.stopped=0;this.mistakes=0;this.repaired=0;this.serial=0;this.quarantineUses=0;this.requests=[];this.effects=[];this.record=[];this.lastLog='当直開始待ち。盤面を選び、伝票の2つの欄を照合してください。';this.zones=Object.fromEntries(ORDER.map(k=>[k,{fixed:false,repairEnd:0,quarantineUntil:0,attacks:0,defended:0,correct:0,missed:0}]));}
 start(){if(this.started)return;this.started=true;this.running=true;this.spawn();this.lastLog='当直開始。最初の伝票が届きました。本人と送信先を照合してください。';}
 spawn(){if(this.serial>=FORMS.length)return;const [type,valid,a,b]=FORMS[this.serial];const r={id:++this.serial,type,valid,a,b,at:this.time,deadline:Math.min(120,this.time+14),status:'pending'};this.requests.push(r);this.effects.push({type,kind:'arrival',at:this.time,id:r.id});if(!valid&&this.zones[type].fixed){r.status='auto';this.stopped++;this.zones[type].defended++;this.effects.push({type,kind:'wall',at:this.time,id:r.id});this.lastLog=TYPES[type].name+'：修正済みの防壁が不正な通信を自動拒否。';}else this.lastLog=TYPES[type].name+'に新しい通信。伝票 #'+String(r.id).padStart(3,'0')+' を審査。';}
 decide(id,allow,timeout=false){const r=this.requests.find(x=>x.id===id);if(!this.running||!r||r.status!=='pending')return false;const zone=this.zones[r.type];r.status=timeout?'timeout':allow?'allow':'deny';r.decisionAt=this.time;r.correct=allow===r.valid;if(allow){this.allowed++;if(r.valid){zone.correct++;this.effects.push({type:r.type,kind:'good',at:this.time,id:r.id});this.lastLog='許可：正常な通信が緑の流れに戻りました。';}else{this.mistakes++;zone.missed++;zone.attacks++;this.data=Math.max(0,this.data-(r.type==='flood'?3:6));this.trust=Math.max(0,this.trust-(r.type==='flood'?5:0));this.effects.push({type:r.type,kind:'attack',at:this.time,id:r.id});this.lastLog=(timeout?'未審査のまま通過。':'誤って許可。')+TYPES[r.type].label+'が盤面に侵入。根本修正で止められます。';}}else{this.stopped++;if(r.valid){this.mistakes++;this.trust=Math.max(0,this.trust-8);this.effects.push({type:r.type,kind:'falseblock',at:this.time,id:r.id});this.lastLog='正常な通信を遮断。利用者の信頼が下がり、緑の流れが途切れました。';}else{zone.correct++;this.effects.push({type:r.type,kind:'stop',at:this.time,id:r.id});this.lastLog='遮断：この伝票の攻撃の芽を消去。抜け道は残ります。';}}this.record.push(r);return true;}
 repair(type){const z=this.zones[type];if(!this.running||!z||z.fixed||z.repairEnd||ORDER.some(k=>this.zones[k].repairEnd))return false;z.repairEnd=this.time+10;this.lastLog=TYPES[type].name+'を修正中。10秒後に防壁ができます。その間も伝票は届きます。';return true;}
 quarantine(type){const z=this.zones[type];if(!this.running||!z||z.fixed||z.quarantineUntil>this.time||this.quarantineUses>=2)return false;z.quarantineUntil=this.time+8;this.quarantineUses++;this.trust=Math.max(0,this.trust-4);this.lastLog=TYPES[type].name+'を8秒隔離。侵食と審査期限を一時停止。利用者の信頼 -4。';return true;}
 advance(dt){if(!this.running||dt<=0)return;const end=Math.min(120,this.time+dt);while(this.time<end){const prev=this.time;this.time=Math.min(end,this.time+.1);for(const r of this.pending()){const z=this.zones[r.type];if(z.quarantineUntil>prev)r.deadline+=Math.max(0,Math.min(this.time,z.quarantineUntil)-prev);}for(const type of ORDER){const z=this.zones[type];if(z.repairEnd&&this.time>=z.repairEnd){z.fixed=true;z.repairEnd=0;z.attacks=0;this.repaired++;this.effects.push({type,kind:'wall',at:this.time,id:0});this.lastLog=TYPES[type].name+'：根本修正完了。侵食が消え、防壁ができました。';}}while(this.serial<FORMS.length&&this.time>=this.serial*7)this.spawn();for(const r of this.requests){if(r.status==='pending'&&this.time>=r.deadline)this.decide(r.id,true,true);}if(Math.floor(prev/4)<Math.floor(this.time/4)){const active=ORDER.reduce((v,k)=>v+(this.zones[k].quarantineUntil>this.time?0:this.zones[k].attacks),0);this.data=Math.max(0,this.data-active);if(this.zones.flood.attacks&&this.zones.flood.quarantineUntil<=this.time)this.trust=Math.max(0,this.trust-this.zones.flood.attacks);}this.effects=this.effects.filter(e=>this.time-e.at<24);}if(this.time>=120){this.running=false;this.done=true;this.lastLog='当直終了。判断の結果を報告書にまとめました。';}}
 pending(type){return this.requests.filter(r=>r.status==='pending'&&(!type||r.type===type));}
}
// B3/S23: normal service activity is an actual cellular automaton.
export function lifeStep(cells,w,h){const next=new Set();for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){let n=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if((dx||dy)&&cells.has((y+dy)*w+x+dx))n++;const key=y*w+x;if(n===3||(n===2&&cells.has(key)))next.add(key);}return next;}
// Different visual grammars; these are game metaphors, not exploit simulations.
export function threatCells(type,age,seed=0){const out=[],step=Math.max(0,Math.floor(age*2));const add=(x,y)=>{if(x>=0&&x<38&&y>=0&&y<18)out.push([x,y]);};if(type==='auth'){const glider=[[[1,0],[2,1],[0,2],[1,2],[2,2]],[[0,1],[2,1],[1,2],[2,2],[1,3]],[[2,1],[0,2],[2,2],[1,3],[2,3]],[[0,1],[1,2],[2,2],[0,3],[1,3]]];const x=Math.min(29,Math.floor(step/3)),y=3+seed%4+Math.floor(step/16);for(const[dx,dy]of glider[step%4])add(2+x+dx,y+dy);}else if(type==='share'){const length=Math.min(30,step+2);for(let x=0;x<length;x++){const mid=8+Math.round(Math.sin(x*.7+seed)*2);add(x+2,mid);if(x>4){const branch=Math.floor((x-4)/4);for(let d=0;d<=Math.min(5,branch);d++)add(x+2,mid+(x%2?d:-d));}}}else if(type==='flood'){for(let y=1;y<17;y++)for(let x=0;x<Math.min(32,step+2);x++)if((x+step)%6<2||((y+seed)%4===0&&x<step%30))add(x+1,y);}else{for(let i=0;i<12;i++){const x=34-((step+i*4)%34);add(x,4+(i*3+seed)%10);if(i%3===0)add(x+1,5+(i*3+seed)%10);}}return out;}
